<script setup lang="ts">
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {commerce,cartCount,openCart,openStore,openHome} from '../../stores/commerce';import {getProduct} from '../../data/catalog';import BottomTabs from '../../components/BottomTabs.vue';import PageHeader from '../../components/PageHeader.vue';import ProductCard from '../../components/ProductCard.vue';import OrderItems from '../../components/OrderItems.vue';import LineIcon from '../../components/LineIcon.vue';
const tab=ref('orders'),expanded=ref('');onLoad(q=>{if(q?.tab==='favorites')tab.value='favorites'});function date(s:string){return new Date(s).toLocaleDateString('zh-CN')}
</script>
<template><view class="screen mine-page"><PageHeader label="我的"/><view class="page-content"><view class="profile"><view class="avatar"><LineIcon name="user" :size="40"/></view><view><text class="page-title">你好，爱分你。</text><text class="muted-note">访客 · 本机演示记录</text></view></view><button role="button" class="mine-cart" @click="openCart"><LineIcon name="cart" :size="28"/><view><text>我的购物车</text><text>{{cartCount}} 件喜欢，等待相遇</text></view><LineIcon name="chevron" :size="20"/></button><view class="mine-tabs"><button role="button" :class="{selected:tab==='orders'}" @click="tab='orders'">我的订单 <text>{{commerce.orders.length}}</text></button><button role="button" :class="{selected:tab==='favorites'}" @click="tab='favorites'">我的收藏 <text>{{commerce.favorites.length}}</text></button></view><view v-if="tab==='orders'"><view v-if="!commerce.orders.length" class="empty-state"><LineIcon name="store" :size="52"/><text>还没有订单</text><text class="body-text">从一份喜欢开始，体验艺术联名。</text><button role="button" class="primary-button" @click="openStore">去商城看看</button></view><view v-for="order in commerce.orders" :key="order.id" class="order-card"><view class="order-heading"><text>{{date(order.createdAt)}}</text><text>演示完成</text></view><OrderItems :items="expanded===order.id?order.items:order.items.slice(0,1)"/><button role="button" class="text-link order-expand" @click="expanded=expanded===order.id?'':order.id">{{expanded===order.id?'收起订单':'查看订单详情'}}<LineIcon :name="expanded===order.id?'back':'chevron'" :size="18"/></button><view v-if="expanded===order.id" class="order-meta"><text>订单号：{{order.id}}</text><text>商品数量：{{order.items.reduce((n,i)=>n+i.quantity,0)}} 件</text><text>演示订单未付款，不会安排发货。</text></view></view></view><view v-else><view v-if="!commerce.favorites.length" class="empty-state"><LineIcon name="heart" :size="52"/><text>把心动，留在这里。</text><text class="body-text">在商品页轻点收藏，下次接着看。</text><button role="button" class="primary-button" @click="openStore">发现喜欢的产品</button></view><view v-else class="favorites"><ProductCard v-for="id in commerce.favorites" :key="id" :product="getProduct(id)"/></view></view><button role="button" class="mine-about" @click="openHome('origin')"><text>关于爱分你</text><LineIcon name="arrow" :size="22"/></button><text class="muted-note local-note">收藏、购物车与演示订单仅保存在当前设备。此版本尚未接入账号、真实支付和物流。</text></view><BottomTabs active="mine"/></view></template>
